# Downloads third-party web assets and license texts into the app's assets.
#   - xterm.js + addons (MIT)           -> app/src/main/assets/term/
#   - D2Coding font (SIL OFL 1.1)       -> app/src/main/assets/term/fonts/  (only if missing; it is committed)
#   - license texts                     -> app/src/main/assets/licenses/
# Go module licenses (Tailscale and all transitive deps) are generated by gen-go-licenses.ps1.
$ErrorActionPreference = 'Stop'
$root   = Split-Path $PSScriptRoot -Parent
$term   = Join-Path $root 'app\src\main\assets\term'
$fonts  = Join-Path $term 'fonts'
$lic    = Join-Path $root 'app\src\main\assets\licenses'
New-Item -ItemType Directory -Force $term, $fonts, $lic | Out-Null

function Get-File($url, $out) {
    Write-Host "  $url"
    Invoke-WebRequest -UseBasicParsing -Uri $url -OutFile $out
}

$XTERM = '6.0.0'; $FIT = '0.11.0'; $UNI = '0.9.0'; $LINKS = '0.12.0'; $WEBGL = '0.19.0'

Write-Host 'xterm.js'
Get-File "https://cdn.jsdelivr.net/npm/@xterm/xterm@$XTERM/lib/xterm.js"                 (Join-Path $term 'xterm.js')
Get-File "https://cdn.jsdelivr.net/npm/@xterm/xterm@$XTERM/css/xterm.css"                (Join-Path $term 'xterm.css')
Get-File "https://cdn.jsdelivr.net/npm/@xterm/addon-fit@$FIT/lib/addon-fit.js"            (Join-Path $term 'addon-fit.js')
Get-File "https://cdn.jsdelivr.net/npm/@xterm/addon-unicode11@$UNI/lib/addon-unicode11.js" (Join-Path $term 'addon-unicode11.js')
Get-File "https://cdn.jsdelivr.net/npm/@xterm/addon-web-links@$LINKS/lib/addon-web-links.js" (Join-Path $term 'addon-web-links.js')
Get-File "https://cdn.jsdelivr.net/npm/@xterm/addon-webgl@$WEBGL/lib/addon-webgl.js" (Join-Path $term 'addon-webgl.js')

if (-not (Test-Path (Join-Path $fonts 'D2Coding-Regular.ttf'))) {
    Write-Host 'D2Coding'
    $tmp = Join-Path ([IO.Path]::GetTempPath()) ("d2coding-" + [guid]::NewGuid())
    New-Item -ItemType Directory $tmp | Out-Null
    Get-File 'https://github.com/naver/d2-coding-font/releases/download/VER1.4.0/D2Coding-Ver1.4.0-20261003.zip' (Join-Path $tmp 'd2.zip')
    Expand-Archive (Join-Path $tmp 'd2.zip') -DestinationPath $tmp
    Copy-Item (Join-Path $tmp 'D2Coding\D2Coding-Ver1.4.0-20261003.ttf')     (Join-Path $fonts 'D2Coding-Regular.ttf')
    Copy-Item (Join-Path $tmp 'D2Coding\D2CodingBold-Ver1.4.0-20261003.ttf') (Join-Path $fonts 'D2Coding-Bold.ttf')
    Remove-Item -Recurse -Force $tmp
}

Write-Host 'License texts'
$licenses = [ordered]@{
    'xterm.LICENSE.txt'             = "https://cdn.jsdelivr.net/npm/@xterm/xterm@$XTERM/LICENSE"
    'xterm-addon-fit.LICENSE.txt'   = "https://cdn.jsdelivr.net/npm/@xterm/addon-fit@$FIT/LICENSE"
    'xterm-addon-unicode11.LICENSE.txt' = "https://cdn.jsdelivr.net/npm/@xterm/addon-unicode11@$UNI/LICENSE"
    'xterm-addon-web-links.LICENSE.txt' = "https://cdn.jsdelivr.net/npm/@xterm/addon-web-links@$LINKS/LICENSE"
    'xterm-addon-webgl.LICENSE.txt' = "https://cdn.jsdelivr.net/npm/@xterm/addon-webgl@$WEBGL/LICENSE"
    'pkg-sftp.LICENSE.txt'          = 'https://raw.githubusercontent.com/pkg/sftp/master/LICENSE'
    'D2Coding.OFL.txt'              = 'https://raw.githubusercontent.com/naver/d2codingfont/master/OFL.txt'
    'tailscale.LICENSE.txt'         = 'https://raw.githubusercontent.com/tailscale/tailscale/main/LICENSE'
    'go.LICENSE.txt'                = 'https://raw.githubusercontent.com/golang/go/master/LICENSE'
    'golang.org-x-crypto.LICENSE.txt' = 'https://raw.githubusercontent.com/golang/crypto/master/LICENSE'
    'golang.org-x-mobile.LICENSE.txt' = 'https://raw.githubusercontent.com/golang/mobile/master/LICENSE'
    'wireguard-go.LICENSE.txt'      = 'https://raw.githubusercontent.com/WireGuard/wireguard-go/master/LICENSE'
    'Apache-2.0.txt'                = 'https://www.apache.org/licenses/LICENSE-2.0.txt'
}
foreach ($name in $licenses.Keys) { Get-File $licenses[$name] (Join-Path $lic $name) }

# Keep the font's own copy next to the font as well (OFL requires the license to accompany the font).
Copy-Item (Join-Path $lic 'D2Coding.OFL.txt') (Join-Path $fonts 'OFL.txt') -Force
Write-Host 'Done.'
